/**
 * DiscReveal website behavior: the looping hero scan demo, the screenshot
 * lightbox, and pulling the current release info live from GitHub so the
 * download section never goes stale.
 *
 * No language-switching logic here on purpose: English (docs/index.html) and
 * German (docs/de/index.html) are two fully pre-rendered pages generated by
 * scripts/buildSeoPages.js, not one page re-rendered client-side. The flag
 * button is a plain link between them. See that script's header comment for
 * why — in short, a crawler that doesn't run JavaScript, or search-engine
 * indexing of a second language, both need real markup at a real URL.
 */
(function () {
    'use strict';

    const REPO = 'markmarkinson/discreveal';
    const pageLanguage = document.documentElement.lang === 'de' ? 'de' : 'en';

    /** Loops the hero's fake scan: rows fade/grow in, bars fill, then it resets. */
    function setupHeroDemo() {
        const rows = Array.from(document.querySelectorAll('.demo-row'));
        const progressFill = document.querySelector('.demo-progress-fill');
        if (!rows.length) return;

        const targets = rows.map((row) => parseFloat(row.dataset.pct) || 0);
        const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

        function setRow(row, index) {
            const fill = row.querySelector('.demo-row-bar-fill');
            const pct = row.querySelector('.demo-row-pct');
            if (fill) fill.style.width = `${targets[index]}%`;
            if (pct) pct.textContent = `${targets[index].toFixed(1)}%`;
        }

        function reset() {
            rows.forEach((row) => {
                row.classList.remove('in');
                const fill = row.querySelector('.demo-row-bar-fill');
                const pct = row.querySelector('.demo-row-pct');
                if (fill) fill.style.width = '0%';
                if (pct) pct.textContent = '';
            });
            if (progressFill) progressFill.style.width = '0%';
        }

        function play() {
            reset();
            if (reduceMotion) {
                rows.forEach((row, index) => {
                    row.classList.add('in');
                    setRow(row, index);
                });
                if (progressFill) progressFill.style.width = '100%';
                return;
            }
            rows.forEach((row, index) => {
                setTimeout(() => {
                    row.classList.add('in');
                    requestAnimationFrame(() => setRow(row, index));
                }, index * 220);
            });
            requestAnimationFrame(() => {
                if (progressFill) progressFill.style.width = '100%';
            });
        }

        play();
        setInterval(play, 6000);
    }

    /**
     * Screenshot lightbox: opens in place over a blurred backdrop instead of navigating to
     * the image file. One shared overlay, filled per slide — same pattern as the in-app
     * modal (renderer/modal.js), just for images instead of confirmations. Captions come
     * from each trigger's data-label (baked in by the page generator), not a dictionary.
     */
    function setupLightbox() {
        const overlay = document.getElementById('lightbox');
        const triggers = Array.from(document.querySelectorAll('.js-lightbox-open'));
        if (!overlay || !triggers.length) return;

        const image = document.getElementById('lightbox-image');
        const labelEl = document.getElementById('lightbox-label');
        const countEl = document.getElementById('lightbox-count');
        const closeBtn = document.getElementById('lightbox-close');
        const prevBtn = document.getElementById('lightbox-prev');
        const nextBtn = document.getElementById('lightbox-next');

        const slides = triggers.map((trigger) => ({
            src: trigger.querySelector('img').src,
            label: trigger.dataset.label || '',
        }));

        let current = 0;
        let lastFocused = null;

        function show(index) {
            current = (index + slides.length) % slides.length;
            const slide = slides[current];
            image.src = slide.src;
            image.alt = slide.label;
            labelEl.textContent = slide.label;
            countEl.textContent = `${current + 1} / ${slides.length}`;
        }

        function onKeydown(event) {
            if (event.key === 'Escape') { event.preventDefault(); close(); }
            else if (event.key === 'ArrowLeft') { event.preventDefault(); show(current - 1); }
            else if (event.key === 'ArrowRight') { event.preventDefault(); show(current + 1); }
            else if (event.key === 'Tab') {
                const buttons = [prevBtn, nextBtn, closeBtn];
                const index = buttons.indexOf(document.activeElement);
                event.preventDefault();
                buttons[(index + (event.shiftKey ? buttons.length - 1 : 1) + buttons.length) % buttons.length].focus();
            }
        }

        const background = Array.from(document.body.children).filter(element => !element.contains(overlay));
        const previousInert = new Map();

        function open(index) {
            lastFocused = document.activeElement;
            show(index);
            overlay.classList.remove('hidden');
            overlay.setAttribute('aria-hidden', 'false');
            document.documentElement.classList.add('no-scroll');
            background.forEach(element => { previousInert.set(element, element.inert); element.inert = true; });
            // The overlay lives inside main, so disable main's other children as well.
            Array.from(overlay.parentElement.children).filter(element => element !== overlay).forEach(element => {
                previousInert.set(element, element.inert); element.inert = true;
            });
            closeBtn.focus();
            document.addEventListener('keydown', onKeydown);
        }

        function close() {
            overlay.classList.add('hidden');
            overlay.setAttribute('aria-hidden', 'true');
            document.documentElement.classList.remove('no-scroll');
            document.removeEventListener('keydown', onKeydown);
            previousInert.forEach((inert, element) => { element.inert = inert; });
            previousInert.clear();
            if (lastFocused && typeof lastFocused.focus === 'function') lastFocused.focus();
        }

        triggers.forEach((trigger, index) => {
            trigger.addEventListener('click', () => open(index));
        });

        // Feature-row screenshots open the same lightbox, at the matching gallery slide,
        // instead of being their own separate (and mostly duplicate) set of slides.
        Array.from(document.querySelectorAll('.js-lightbox-feature')).forEach((trigger) => {
            const index = Number(trigger.dataset.openIndex);
            if (Number.isInteger(index) && slides[index]) {
                trigger.addEventListener('click', () => open(index));
            }
        });

        closeBtn.addEventListener('click', close);
        prevBtn.addEventListener('click', () => show(current - 1));
        nextBtn.addEventListener('click', () => show(current + 1));
        // Click on the scrim itself (not the frame or its buttons) closes, like the app's own modal overlay.
        overlay.addEventListener('click', (event) => {
            if (event.target === overlay) close();
        });
    }

    /**
     * Pulls the latest GitHub release so every download button/the version line never goes
     * stale. Three buttons point at a download in total — the hero CTA, the final CTA band,
     * and the one in the actual Download section — all marked .js-download-link so a visitor
     * clicking "Download for Windows" at the top of the page downloads immediately instead of
     * being sent to scroll down to the Download section first (reported directly: that jump
     * read as the button not actually working).
     */
    function setupReleaseInfo() {
        const downloadLinks = Array.from(document.querySelectorAll('.js-download-link'));
        const versionEl = document.getElementById('download-version');
        if (!downloadLinks.length) return;

        fetch(`https://api.github.com/repos/${REPO}/releases/latest`, {
            headers: { Accept: 'application/vnd.github+json' },
        })
            .then((response) => (response.ok ? response.json() : Promise.reject(new Error('release fetch failed'))))
            .then((release) => {
                const asset = (release.assets || []).find((item) => item.name === 'discreveal-portable.exe');
                const officialDownload = asset && /^https:\/\/github\.com\/markmarkinson\/discreveal\/releases\/download\/[^/]+\/discreveal-portable\.exe$/.test(asset.browser_download_url || '')
                    ? asset.browser_download_url : null;
                if (officialDownload) downloadLinks.forEach((link) => { link.href = officialDownload; });
                if (versionEl) {
                    const sizeMb = asset && Number.isFinite(asset.size) ? (asset.size / 1e6).toLocaleString(
                        pageLanguage === 'de' ? 'de-DE' : 'en-US', {minimumFractionDigits:1,maximumFractionDigits:1}
                    ) : null;
                    const date = new Date(release.published_at).toLocaleDateString(
                        pageLanguage === 'de' ? 'de-DE' : 'en-US'
                    );
                    const strong = document.createElement('strong');
                    strong.textContent = 'DiscReveal Portable';
                    versionEl.replaceChildren(strong, document.createTextNode(sizeMb
                        ? ` · ${sizeMb} MB · ${date}` : ` · ${date}`));
                }
            })
            .catch(() => {
                // Repo private, offline, or rate-limited: the button already points at the
                // direct latest EXE download (set in the HTML), which works without this enhancement.
                // Keep the baked-in release facts visible for visitors and crawlers.
            });
    }

    document.addEventListener('DOMContentLoaded', () => {
        setupHeroDemo();
        setupReleaseInfo();
        setupLightbox();
    });
})();
